let questions=[],questionTab='personal',answerGenerating=false;
try{const loaded=JSON.parse(localStorage.getItem('homework-questions-v1')||'[]');questions=Array.isArray(loaded)?loaded:[]}catch{}
for(const q of questions){q.classId=q.classId||DEFAULT_CLASS}
async function commitQuestions(next){try{if(cloud.ready){await cloudSaveQuestions(next);questions=next;return true}localStorage.setItem('homework-questions-v1',JSON.stringify(next));if(typeof trackUsage==='function'){for(const q of next){const before=questions.find(x=>x.id===q.id);if(!before)trackUsage('question_asked');else if(q.answer&&JSON.stringify(q.answer)!==JSON.stringify(before.answer))trackUsage('answer_published')}}questions=next;return true}catch(e){alert(cloud.ready?'שמירת השאלה או התשובה בשרת נכשלה: '+e.message:'שמירת השאלה או התשובה נכשלה. האחסון בדפדפן חסום או מלא.');return false}}
function visibleQuestion(q,currentRole,viewer,tab){if(q.classId!==activeClassId())return false;if(tab==='class')return q.classId===activeClassId()&&q.answer?.status==='published'&&q.answer.visibility==='class';return currentRole==='teacher'||(q.familyId===viewer&&q.authorRole===currentRole);}
function visibleAnswer(q,currentRole,viewer){return q.classId===activeClassId()&&q.answer?.status==='published'&&(currentRole==='teacher'||q.answer.visibility==='class'||(q.familyId===viewer&&q.authorRole===currentRole));}
document.getElementById('sendQuestion').onclick=async()=>{if(role==='teacher'||!activeStudentId())return;const input=document.getElementById('newQuestion'),text=input.value.trim();if(!text){document.getElementById('questionStatus').textContent='כתבו שאלה לפני השליחה.';return}const q={id:crypto.randomUUID(),familyId:activeStudentId(),classId:activeClassId(),authorRole:role,author:role==='parent'?'הורה':'תלמיד',subject:document.getElementById('questionSubject').value,text,createdAt:new Date().toISOString(),draft:null,answer:null};if(await commitQuestions([...questions,q])){input.value='';document.getElementById('questionStatus').textContent=cloud.ready?'✓ השאלה נשלחה למורה.':'✓ השאלה נשמרה למורה במכשיר הזה.';questionTab='personal';renderQuestions()}};
document.getElementById('personalQuestions').onclick=async()=>{questionTab='personal';renderQuestions()};document.getElementById('classQuestions').onclick=async()=>{questionTab='class';renderQuestions()};
function renderQuestions(){
 document.getElementById('questionComposer').hidden=role==='teacher';document.getElementById('personalQuestions').textContent=role==='teacher'?'כל השאלות למורה':'השאלות שלנו';document.getElementById('personalQuestions').classList.toggle('active',questionTab==='personal');document.getElementById('classQuestions').classList.toggle('active',questionTab==='class');const list=document.getElementById('questionList');list.replaceChildren();const shown=questions.filter(q=>visibleQuestion(q,role,activeStudentId(),questionTab)).slice().reverse();if(!shown.length)list.append(el('p',questionTab==='class'?'אין עדיין שאלות ותשובות שהמורה פרסם לכיתה.':'אין עדיין שאלות. אפשר להתחיל בשאלה הראשונה.'));
 for(const q of shown){const card=el('article',null,'panel');card.style.marginTop='12px';card.append(el('h3',q.subject),el('div',questionTab==='class'?'שאלה ותשובה לכיתה':q.author+' · '+new Date(q.createdAt).toLocaleString(siteLocale()),'meta'));const question=userEl('p',questionTab==='class'?q.answer.publicQuestion:q.text);question.style.whiteSpace='pre-wrap';card.append(question);
 if(visibleAnswer(q,role,activeStudentId())){const answer=el('div',null,'notice');const text=userEl('p',q.answer.text);text.style.whiteSpace='pre-wrap';answer.append(el('b','תשובת המורה'),text,el('div',(q.answer.visibility==='class'?'פורסם לכיתה':'תשובה פרטית לשואל ולמורה')+' · '+q.answer.teacher,'meta'));card.append(answer)}else card.append(el('span','ממתין לתשובת המורה','badge'));
 if(role==='teacher'&&(typeof teacherPermission!=='function'||teacherPermission('can_answer_questions',q.classId))){card.append(replyEditor(q))}list.append(card)}
}
function replyEditor(q){
 const box=el('div');box.style.marginTop='18px';const title=el('label','שם המורה');const teacher=el('input');teacher.maxLength=60;teacher.value=q.draft?.teacher||q.answer?.teacher||'';title.append(teacher);
 const label=el('label','תשובה לבדיקה ועריכה');const draft=el('textarea');draft.rows=5;draft.maxLength=6000;draft.value=q.draft?.text||q.answer?.text||'';label.append(draft);
 const scopeLabel=el('label','למי לפרסם?');const scope=el('select');[['private','פרטי — השואל והמורה'],['class','לכל הכיתה — שאלה ותשובה']].forEach(([value,text])=>{const option=el('option',text);option.value=value;if(value==='class'&&!teacherPermission('can_publish_class_answers',q.classId))option.disabled=true;scope.append(option)});scope.value=q.draft?.visibility||q.answer?.visibility||'private';scopeLabel.append(scope);
 const publicLabel=el('label','נוסח השאלה לפרסום בכיתה — אפשר להסיר פרטים אישיים');const publicQuestion=el('textarea');publicQuestion.rows=2;publicQuestion.maxLength=2000;publicQuestion.value=q.draft?.publicQuestion||q.answer?.publicQuestion||q.text;publicLabel.append(publicQuestion);publicLabel.hidden=scope.value!=='class';
 const checkLabel=el('label');checkLabel.style.cssText='display:flex;gap:8px;align-items:center';const approve=el('input');approve.type='checkbox';approve.style.width='auto';checkLabel.append(approve,el('span','בדקתי את השאלה והתשובה ואני מאשר/ת לפרסם לקהל שבחרתי'));
 const status=el('p');status.setAttribute('role','status');const invalidate=()=>{approve.checked=false;status.textContent='השינוי דורש אישור מחדש לפני פרסום.'};[draft,teacher,publicQuestion].forEach(input=>input.oninput=invalidate);scope.onchange=()=>{publicLabel.hidden=scope.value!=='class';invalidate()};
 const data=()=>({text:draft.value.trim(),teacher:teacher.value.trim(),visibility:scope.value,publicQuestion:publicQuestion.value.trim()});
 const save=el('button','שמירת טיוטה','secondary');save.type='button';save.onclick=async()=>{if(answerGenerating)return;const d=data();if(await commitQuestions(questions.map(x=>x.id===q.id?{...x,draft:d}:x)))status.textContent='הטיוטה נשמרה למורה בלבד.'};
 const generate=el('button','✨ טיוטת תשובה בעזרת AI','secondary');generate.type='button';generate.disabled=answerGenerating;generate.onclick=async()=>generateAnswer(q,data());
 const publish=el('button','אישור ופרסום תשובה','button');publish.type='button';publish.onclick=async()=>{if(!teacherPermission('can_answer_questions',q.classId)||(scope.value==='class'&&!teacherPermission('can_publish_class_answers',q.classId))){status.textContent=t('אין הרשאה לפרסום התשובה.');return}if(answerGenerating){status.textContent='המתינו לסיום יצירת הטיוטה.';return}const d=data();if(!d.text||!d.teacher){status.textContent='מלאו שם מורה ותשובה.';return}if(!approve.checked){status.textContent='נדרש אישור מפורש של המורה לפני פרסום.';return}if(d.visibility==='class'&&!d.publicQuestion){status.textContent='הוסיפו נוסח שאלה לפרסום לכיתה.';return}const updated=questions.map(x=>x.id===q.id?{...x,draft:null,answer:{...d,status:'published',publishedAt:new Date().toISOString()}}:x);if(await commitQuestions(updated))renderQuestions()};
 box.append(title,label,generate,save,scopeLabel,publicLabel,checkLabel,publish,status);return box;
}
async function generateAnswer(q,draft){
 if(answerGenerating)return;const status=document.getElementById('answerAiStatus');if(!navigator.gpu){status.textContent='יצירת תשובת AI דורשת WebGPU. אפשר לכתוב תשובה ידנית ולבדוק אותה לפני פרסום.';return}if(draft.text&&!confirm('ליצור טיוטה חדשה במקום טקסט התשובה הנוכחי?'))return;
 // Save before generation so teacher edits survive a model load failure.
 if(!await commitQuestions(questions.map(x=>x.id===q.id?{...x,draft}:x)))return;
 answerGenerating=true;renderQuestions();status.textContent='טוען מודל מקומי ליצירת טיוטת תשובה…';let worker=null;
 try{worker=new Worker('./ai-explanation-worker.js',{type:'module'});const task=classRecords().find(r=>r.subject===q.subject&&r.day===key(dates[selected]));const text=await new Promise((resolve,reject)=>{worker.onmessage=({data})=>{if(data.type==='progress')status.textContent='טוען מודל תשובה… '+Math.round(data.progress||0)+'%';if(data.type==='running')status.textContent='מנסח טיוטת תשובה למורה…';if(data.type==='result')resolve(data.text);if(data.type==='error')reject(new Error(data.message))};worker.onerror=()=>reject(new Error('טעינת מודל התשובה נכשלה.'));worker.postMessage({id:1,language:languageName(),question:q.text,subject:q.subject,instructions:JSON.stringify({homework:task?.details||'',lesson:task?.lesson||null}),resources:[]})});if(typeof trackUsage==='function')trackUsage('ai_draft_used',q.classId);if(await commitQuestions(questions.map(x=>x.id===q.id?{...x,draft:{...draft,text:String(text).slice(0,6000)}}:x)))status.textContent='הטיוטה מוכנה לבדיקה. היא לא פורסמה ולא אושרה אוטומטית.';}
 catch(e){status.textContent='יצירת הטיוטה נכשלה: '+e.message+' אפשר להשיב ידנית.'}
 finally{if(worker)worker.terminate();answerGenerating=false;renderQuestions()}
}
renderQuestions();
